], ["المأخذ الأرضي", ["ثلاثة مرابط: الطور والحيادي والأرض"]], ["الطور", ["سلك بغلاف أحمر أو بني، موصّل بتيار ذي توتر 220 V", "يسبب الصدمة عند لمسه وحده أو مع الحيادي"]], ["الحيادي والأرضي", ["الحيادي: غلاف أزرق، غير موصّل بتيار", "الأرضي: غلاف أصفر وأخضر، موصّل بالأرض"]]], "K": "الطور (أحمر/بني) خطير، الحيادي (أزرق)، الأرضي (أصفر وأخضر) يحمي من الصعق.", "M": ["أميز الأسلاك بألوانها", "أستعمل مفك كاشف التيار للطور فقط", "لا ألمس الطور أبدا"], "X": "الطور هو السلك الحي: التوتر بينه وبين الحيادي (أو الأرض) حوالي 220 V، بينما التوتر بين الحيادي والأرض يساوي 0 V.", "EX": [["قيس التوتر بين المرابط الثلاثة A وB وC لمأخذ: بين A وB يساوي 230 V، وبين A وC يساوي 0 V، وبين B وC يساوي 230 V. عيّن كل مربط.", "التوتر بين A وC يساوي 0 V فهما الحيادي والأرضي. التوتر بين B وكل من A وC يساوي 230 V فـ B هو الطور"], ["لماذا يضيء مصباح مفك كاشف التيار عند لمس الطور فقط؟", "لأن الطور موصّل بتيار كهربائي ذي توتر عال، فتمرّ شدة صغيرة عبر المفك فيضيء. أما الحيادي فلا يغذي المصباح"]]}, {"n": 28, "m": 2, "i": "⚠️", "t": "أخطار التيار الكهربائي", "B": [["عيوب العزل", ["ارتفاع حرارة الأسلاك وانصهار المادة العازلة وتعرّيها", "فتحدث ملامسة الطور والحيادي (استقصار) أو ملامسة الطور للهيكل المعدني"]], ["زيادة الشدة والحمولة", ["تشغيل عدة أجهزة معا (غسالة، مكيف، تلفاز...) يرفع شدة التيار فوق القيمة المقبولة", "يسبب قطع القاطع أو تلف الأجهزة أو حريقا"]], ["الصدمة الكهربائية", ["الجسم يصبح جزءا من دارة مغلقة والجلد الرطب ناقل جيد", "توتر متناوب أكبر من 25 V في ظروف رطبة قد يكون مميتا"]], ["النتائج", ["حوادث مميتة: تيار متناوب بشدة 40 mA يسبب صعقة قاتلة", "حرائق وتلف الأجهزة"]]], "K": "أخطار التيار: الاستقصار، زيادة الشدة والحمولة، والصعق الكهربائي بملامسة الطور.", "M": ["أتجنب الأسلاك العارية", "لا أشغل عدة أجهزة قوية على مأخذ واحد", "أحافظ على جفاف اليدين"], "X": "الطائر على سلك كهربائي لا يتأذى لأنه يلمس خطا واحدا فلا تُغلق دارة عبر جسمه، لكنه إذا لمس سلكين معا أُغلقت الدارة فمات.", "EX": [["شخص مقاومة جسمه 1000 Ω. ما أكبر توتر يتعرض له دون خطر إذا كان لا يتحمل شدة أكبر من 50 mA؟", "`U = R × I = 1000 × 0,05 = 50 V`"], ["عامل صيانة تعرض لتوتر قيمته العظمى 532 V ومقاومة جسمه 1200 Ω. ما القيمة العظمى للشدة بالمللي أمبير؟", "`I_{max} = U_{max}/R = 532/1200 ≈ 0,443 A ≈ 443 mA`. وهي أكبر بكثير من 40 mA (حد الخطر) فالصعق مميت"]]}, {"n": 29, "m": 2, "i": "🛡️", "t": "وسائل الأمن: التأريض والمنصهرة", "B": [["التوصيل الأرضي", ["نقل التيار المتسرب من الشبكة إلى الأرض لحماية الأشخاص من الصعق"]], ["المنصهرة", ["سلك ينصهر إذا تجاوزت الشدة الحد المسجل عليها فتفتح الدارة"]], ["تركيبها", ["دائما على سلك الطور"]], ["القاطعة", ["تركّب على الطور دائما لتفادي الصعق عند تغيير المصابيح"]]], "K": "التأريض يحمي الأشخاص، والمنصهرة تحمي الدارة من زيادة الشدة، وكلاهما على الطور.", "M": ["أركّب القاطعة والمنصهرة على الطور", "أوصل الأجهزة المعدنية بالأرض", "أستعمل منصهرة مناسبة للشدة"], "X": "الهيكل المعدني المؤرَّض يوصل أي تسرّب كهربائي إلى الأرض بدل أن يمر عبر جسم الإنسان.", "EX": [["لماذا نركّب المنصهرة والقاطعة على سلك الطور؟", "لأن الطور هو السلك الحي: قطعه بالمنصهرة أو القاطعة يعزل الجهاز عن التيار ويحمي الأشخاص عند التدخل"], ["ما دور سلك التأريض في غسالة هيكلها معدني؟", "إذا لامس الطور الهيكل المعدني انتقل التيار إلى الأرض بسلك التأريض فلا تحدث صعقة عند لمس الغسالة"]]}, {"n": 30, "m": 2, "i": "🔒", "t": "القواطع الكهربائية", "B": [["القاطع الرئيسي", ["يركّب بعد العدّاد، حساسيته حوالي 500 mA عادة", "يفصل تلقائيا عند تجاوز الحد وعند خلل خارج الشبكة"]], ["القاطع التفاضلي", ["يقارن شدة التيار في الطور والحيادي", "إذا اختلفتا (تسرب إلى الأرض) فصل التيار آليا", "حساسيته عادة 30 mA"]], ["القاطع التقسيمي (الجزئي)", ["يحمي دارة واحدة من الشدة الزائدة عن الحد", "وقد حل محل المنصهرة في التركيبات الحديثة"]], ["اللوح الكهربائي", ["العناصر الأساسية: القواطع التفاضلية والتقسيمية والمنصهرات"]]], "K": "القاطع التفاضلي (30 mA) يحمي الأشخاص من الصعق، والتقسيمي يحمي كل دارة من زيادة الشدة.", "M": ["التفاضلي لتسرب التيار إلى الأرض", "التقسيمي لزيادة الحمولة", "الرئيسي بعد العدّاد"], "X": "القاطع التفاضلي يعمل كحارس: إن لاحظ أن ما يخرج من الطور لا يساوي ما يعود في الحيادي عرف أن جزءا ذهب إلى الأرض (عبر جسم شخص مثلا) فيقطع التيار.", "EX": [["قاطع تفاضلي حساسيته 30 mA. ماذا يحدث إذا تسرب تيار شدته 40 mA عبر شخص؟", "40 mA أكبر من 30 mA فيقطع القاطع التيار آليا فيحمي الشخص"], ["ما الفرق بين المنصهرة والقاطع التفاضلي؟", "المنصهرة تحمي الدارة من زيادة الشدة بانصهار سلكها (يجب استبدالها). التفاضلي يحمي الأشخاص بقطع التيار عند تسرب إلى الأرض ويعاد تشغيله"]]}, {"n": 31, "m": 2, "i": "🏠", "t": "قواعد الأمن في مخطط شبكة منزلية وحساب الحمولة", "B": [["التركيب", ["خط التوزيع إلى العدّاد: الحيادي موصول بالأرض", "يوصل الطور والحيادي بالعداد ثم بالقاطع التفاضلي"]], ["الخطوط", ["تنطلق خطوط التوزيع من التفاضلي مرورا بلوحة التوزيع", "كل خط محمي بمنصهرة أو قاطع تقسيمي على مربط الطور"]], ["الحمولة", ["`P = U × I` فـ `I = P / U`", "مجموع استطاعات الأجهزة المشغلة معا يحدد الشدة"]], ["التطبيق", ["عند تشغيل أجهزة معا نقارن الشدة المحسوبة بقيمة القاطع"]]], "K": "كل خط محمي على الطور بقاطع تقسيمي، والتفاضلي للحماية العامة، وشدة التيار تحسب من P = U × I.", "M": ["أجمع الاستطاعات", "أحسب `I = P/U`", "أقارن بقيمة المنصهرة أو القاطع"], "X": "الأجهزة القوية تسحب شدة كبيرة؛ فإذا شغلناها كلها معا قد تتجاوز الشدة قيمة القاطع فينقطع التيار.", "EX": [["مطبخ فيه أجهزة استطاعاتها 1200 W و850 W و2000 W و1500 W تعمل معا على 220 V وقاطع 20 A. هل يقطع القاطع التيار؟", "`P = 1200 + 850 + 2000 + 1500 = 5550 W`. `I = P/U = 5550/220 ≈ 25,2 A`. وهي أكبر من 20 A فيقطع القاطع التيار (زيادة الحمولة)"], ["غسالة استطاعتها 4,4 kW على 220 V موصولة بمنصهرة 10 A. هل يمكن تشغيلها بأمان؟", "`I = P/U = 4400/220 = 20 A`. وهي أكبر من 10 A فتنصهر المنصهرة. الحل: تغيير المنصهرة بأخرى مناسبة (أكبر من 20 A) وسلك أسمك وخط خاص بالغسالة"]]}];
